class Solution:
    def romanToInt(self, s: str) -> int:
        values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        total = 0
        max_seen = 0
        for ch in reversed(s):
            value = values[ch]
            if value < max_seen:
                total -= value
            else:
                total += value
                max_seen = value
        return total

